FONTES = {'backend/app/models/historico_campos_pdf.py': 'from sqlalchemy import CheckConstraint, Index, Integer, String, UniqueConstraint\nfrom sqlalchemy.orm import Mapped, mapped_column\nfrom backend.app.database.base import Base\n\n\nclass HistoricoCampoPdf(Base):\n    __tablename__ = "historico_campos_pdf"\n    __table_args__ = (\n        UniqueConstraint("usuario_admin_id", "campo", "chave_valor", name="uq_historico_campo_pdf_valor"),\n        CheckConstraint("usuario_admin_id > 0", name="ck_historico_campo_pdf_usuario"),\n        Index("ix_historico_campo_pdf_usuario_data", "usuario_admin_id", "atualizado_em"),\n    )\n    id: Mapped[int] = mapped_column(Integer, primary_key=True)\n    usuario_admin_id: Mapped[int] = mapped_column(Integer, nullable=False)\n    campo: Mapped[str] = mapped_column(String(32), nullable=False)\n    chave_valor: Mapped[str] = mapped_column(String(64), nullable=False)\n    valor: Mapped[str] = mapped_column(String(180), nullable=False)\n    atualizado_em: Mapped[str] = mapped_column(String(32), nullable=False)\n', 'backend/app/schemas/historico_campos_pdf.py': 'from typing import Literal\nfrom pydantic import BaseModel, ConfigDict, Field, model_validator\nfrom backend.app.schemas.preparacao_pdf import CamposCarimbo\n\nCampoHistoricoPdf = Literal["descricao", "codigo_tecnico", "material", "quantidade", "dureza",\n    "tratamento_termico", "revestimento", "escala", "unidade", "revisao",\n    "tolerancias_gerais", "sobremetal", "observacoes_servico"]\nLIMITES = {"descricao":80, "codigo_tecnico":30, "material":50, "quantidade":7, "dureza":40,\n    "tratamento_termico":60, "revestimento":60, "escala":24, "unidade":16,\n    "revisao":16, "tolerancias_gerais":180, "sobremetal":80, "observacoes_servico":180}\n\n\nclass ValorHistoricoPdf(BaseModel):\n    model_config = ConfigDict(extra="forbid", str_strip_whitespace=True)\n    campo: CampoHistoricoPdf\n    valor: str = Field(min_length=1, max_length=180)\n\n    @model_validator(mode="after")\n    def validar_valor(self):\n        if len(self.valor) > LIMITES[self.campo]:\n            raise ValueError("valor_do_historico_excede_limite")\n        CamposCarimbo.texto_imprimivel(self.valor)\n        if self.campo == "quantidade":\n            if not self.valor.isascii() or not self.valor.isdecimal() or not 1 <= int(self.valor) <= 1_000_000:\n                raise ValueError("quantidade_do_historico_invalida")\n            self.valor = str(int(self.valor))\n        return self\n\n\nclass GuardarHistoricoPdf(BaseModel):\n    model_config = ConfigDict(extra="forbid")\n    itens: list[ValorHistoricoPdf] = Field(min_length=1, max_length=650)\n', 'backend/app/services/historico_campos_pdf.py': 'from datetime import datetime, timezone\nimport hashlib\nimport json\nfrom sqlalchemy import select\nfrom backend.app.models.historico_campos_pdf import HistoricoCampoPdf\nfrom backend.app.models.preparacao_pdf import PreparacaoPdfCotacao\nfrom backend.app.schemas.historico_campos_pdf import GuardarHistoricoPdf, ValorHistoricoPdf, LIMITES\nfrom backend.app.services.preparacao_pdf import ServicoPreparacaoPdf\nfrom backend.app.services.documentacao_cotacao import travar_documentacao\n\n\ndef chave_valor(valor: str) -> str:\n    return hashlib.sha256(" ".join(valor.split()).casefold().encode()).hexdigest()\n\n\nclass ServicoHistoricoCamposPdf:\n    def __init__(self, banco):\n        self.banco = banco\n\n    def listar(self, usuario):\n        ServicoPreparacaoPdf.exigir_admin(usuario)\n        valores = {campo: [] for campo in LIMITES}\n        vistos = {campo: set() for campo in LIMITES}\n\n        def incluir(campo, valor):\n            try:\n                item = ValorHistoricoPdf(campo=campo, valor=str(valor))\n            except (ValueError, TypeError):\n                return\n            chave = chave_valor(item.valor)\n            if chave not in vistos[campo]:\n                vistos[campo].add(chave)\n                valores[campo].append(item.valor)\n\n        registros = self.banco.scalars(select(HistoricoCampoPdf).where(\n            HistoricoCampoPdf.usuario_admin_id == usuario.usuario_id).order_by(\n            HistoricoCampoPdf.atualizado_em.desc(), HistoricoCampoPdf.id.desc()))\n        for item in registros:\n            incluir(item.campo, item.valor)\n        # Leitura das configurações antigas: não modifica PDFs ou o histórico.\n        anteriores = self.banco.scalars(select(PreparacaoPdfCotacao.configuracao_json).where(\n            PreparacaoPdfCotacao.usuario_admin_id == usuario.usuario_id).order_by(\n            PreparacaoPdfCotacao.criado_em.desc(), PreparacaoPdfCotacao.id.desc()))\n        for configuracao in anteriores:\n            try:\n                paginas = json.loads(configuracao)\n            except (ValueError, TypeError):\n                continue\n            if not isinstance(paginas, list):\n                continue\n            for pagina in paginas:\n                campos = pagina.get("campos") if isinstance(pagina, dict) else None\n                if isinstance(campos, dict):\n                    for campo, valor in campos.items():\n                        if campo in LIMITES and isinstance(valor, (str, int)) and not isinstance(valor, bool):\n                            incluir(campo, valor)\n        return {"campos": valores}\n\n    def guardar(self, dados: GuardarHistoricoPdf, usuario):\n        ServicoPreparacaoPdf.exigir_admin(usuario)\n        itens = {(item.campo, chave_valor(item.valor)): item.valor for item in dados.itens}\n        # A transação curta impede duplicação em duas abas do mesmo ADM.\n        travar_documentacao(self.banco)\n        agora = datetime.now(timezone.utc).isoformat(timespec="microseconds").replace("+00:00", "Z")\n        try:\n            for (campo, chave), valor in itens.items():\n                item = self.banco.scalar(select(HistoricoCampoPdf).where(\n                    HistoricoCampoPdf.usuario_admin_id == usuario.usuario_id,\n                    HistoricoCampoPdf.campo == campo, HistoricoCampoPdf.chave_valor == chave))\n                if item is None:\n                    item = HistoricoCampoPdf(usuario_admin_id=usuario.usuario_id, campo=campo,\n                        chave_valor=chave, valor=valor, atualizado_em=agora)\n                    self.banco.add(item)\n                else:\n                    item.valor = valor\n                    item.atualizado_em = agora\n            self.banco.commit()\n        except Exception:\n            self.banco.rollback()\n            raise\n        return {"guardados": len(itens)}\n', 'backend/app/api/rotas/preparacao_pdf.py': 'from typing import Annotated\nfrom fastapi import APIRouter, Depends, Query, Request, Response\nfrom fastapi.responses import FileResponse\nfrom sqlalchemy.orm import Session\nfrom backend.app.database.sessao import obter_banco\nfrom backend.app.schemas.preparacao_pdf import PrepararPdf, PreparacaoPdfResposta\nfrom backend.app.services.preparacao_pdf import ServicoPreparacaoPdf\nfrom backend.app.schemas.historico_campos_pdf import GuardarHistoricoPdf\nfrom backend.app.services.historico_campos_pdf import ServicoHistoricoCamposPdf\n\nroteador = APIRouter(prefix="/administracao/preparacao-pdf", tags=["preparação de PDF para cotação"])\nSessaoBanco = Annotated[Session, Depends(obter_banco)]\n\n\ndef servico(banco, request):\n    s = ServicoPreparacaoPdf(banco)\n    s.exigir_admin(request.state.usuario_acesso)\n    return s\n\n\n@roteador.get("/historico-campos")\ndef historico_campos(banco: SessaoBanco, request: Request):\n    return ServicoHistoricoCamposPdf(banco).listar(request.state.usuario_acesso)\n\n\n@roteador.post("/historico-campos")\ndef guardar_historico_campos(dados: GuardarHistoricoPdf, banco: SessaoBanco, request: Request):\n    return ServicoHistoricoCamposPdf(banco).guardar(dados, request.state.usuario_acesso)\n\n\n@roteador.get("/arquivos/{arquivo_id}")\ndef informacoes(arquivo_id: int, banco: SessaoBanco, request: Request):\n    from backend.app.services.motor_pdf_cotacao import informacoes as ler\n    s = servico(banco, request)\n    item = s.original(arquivo_id)\n    return {**ler(s.conteudo_original(arquivo_id)), "arquivo_id": item.id, "sha256": item.sha256,\n            "preparacoes": s.listar(arquivo_id)}\n\n\n@roteador.get("/arquivos/{arquivo_id}/paginas/{pagina}")\ndef imagem_original(arquivo_id: int, pagina: int, banco: SessaoBanco, request: Request,\n                    sha256: str = Query(pattern=r"^[a-f0-9]{64}$")):\n    from backend.app.services.motor_pdf_cotacao import imagem_pagina\n    s = servico(banco, request)\n    return Response(imagem_pagina(s.conteudo_original(arquivo_id, sha256), pagina), media_type="image/png")\n\n\n@roteador.post("/arquivos/{arquivo_id}", response_model=PreparacaoPdfResposta)\ndef preparar(arquivo_id: int, dados: PrepararPdf, banco: SessaoBanco, request: Request):\n    return servico(banco, request).criar(arquivo_id, dados, request.state.usuario_acesso)\n\n\n@roteador.get("/versoes/{preparacao_id}/download", response_class=FileResponse)\ndef baixar(preparacao_id: int, banco: SessaoBanco, request: Request):\n    s = servico(banco, request)\n    p = s.obter(preparacao_id)\n    return FileResponse(s.caminho(p), media_type="application/pdf", filename=f"mec-arquivo-{p.arquivo_id}-versao-{p.versao}.pdf")\n\n\n@roteador.get("/versoes/{preparacao_id}/paginas/{pagina}")\ndef imagem_preparada(preparacao_id: int, pagina: int, banco: SessaoBanco, request: Request):\n    from backend.app.services.motor_pdf_cotacao import imagem_pagina\n    s = servico(banco, request)\n    p = s.obter(preparacao_id)\n    return Response(imagem_pagina(s.caminho(p).read_bytes(), pagina), media_type="image/png")\n', 'frontend/src/pages/documentacao/CampoPdfComHistorico.tsx': 'import { useEffect, useId, useRef, useState } from "react";\n\ntype Props = { label: string; nome: string; valor: string | number; valores: string[];\n  limite: number; numero?: boolean; multiline?: boolean; placeholder?: string; disabled: boolean;\n  onMudar: (valor: string) => void; onGuardar: (valor: string) => void };\n\nexport default function CampoPdfComHistorico({ label, nome, valor, valores, limite, numero,\n  multiline, placeholder, disabled, onMudar, onGuardar }: Props) {\n  const id = useId(); const raiz = useRef<HTMLDivElement>(null);\n  const campo = useRef<HTMLInputElement | HTMLTextAreaElement | null>(null);\n  const [aberto, setAberto] = useState(false); const [busca, setBusca] = useState("");\n  useEffect(() => {\n    if (!aberto) return;\n    const fechar = (e: globalThis.PointerEvent) => { if (!raiz.current?.contains(e.target as Node)) setAberto(false); };\n    document.addEventListener("pointerdown", fechar);\n    return () => document.removeEventListener("pointerdown", fechar);\n  }, [aberto]);\n  useEffect(() => { if (disabled) setAberto(false); }, [disabled]);\n  const texto = (v: string) => v.normalize("NFD").replace(/[\\u0300-\\u036f]/g, "").toLowerCase();\n  const opcoes = valores.filter(v => texto(v).includes(texto(busca)));\n  const atributos = { id, value: valor, disabled, placeholder,\n    onChange: (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => onMudar(e.currentTarget.value),\n    onBlur: (e: React.FocusEvent<HTMLInputElement | HTMLTextAreaElement>) => onGuardar(e.currentTarget.value),\n    onKeyDown: (e: React.KeyboardEvent<HTMLInputElement | HTMLTextAreaElement>) => {\n      if (e.key === "ArrowDown" && !disabled) { e.preventDefault(); setBusca(""); setAberto(true); }\n      if (e.key === "Escape") setAberto(false);\n    } };\n  return <div className="pdf50-campo" ref={raiz} onKeyDown={e => { if (e.key === "Escape") { setAberto(false); campo.current?.focus(); } }}>\n    <label htmlFor={id}>{label}<span className="pdf50-controle">\n      {multiline ? <textarea {...atributos} maxLength={limite} ref={el => { campo.current = el; }} /> :\n        <input {...atributos} type={numero ? "number" : "text"} {...(numero ? { min:1, max:limite } : { maxLength:limite })} ref={el => { campo.current = el; }} />}\n      <button className="pdf50-seta" type="button" disabled={disabled} aria-label={`Selecionar ${nome} do histórico`} title={`Selecionar ${nome} do histórico`}\n        aria-haspopup="listbox" aria-expanded={aberto} aria-controls={`${id}-opcoes`} onMouseDown={e => e.preventDefault()}\n        onClick={() => { setBusca(""); setAberto(v => !v); }}>▾</button>\n    </span></label>\n    {aberto && <div className="pdf50-menu" onBlur={e => { if (!e.currentTarget.contains(e.relatedTarget as Node)) setAberto(false); }}>\n      <input type="search" aria-label={`Buscar ${nome} no histórico`} placeholder="Buscar no histórico…" value={busca} onChange={e => setBusca(e.target.value)} />\n      <div id={`${id}-opcoes`} role="listbox" aria-label={`Histórico de ${nome}`}>\n        {opcoes.map(v => <button type="button" role="option" aria-selected={String(valor) === v} key={v} onClick={() => {\n          onMudar(v); onGuardar(v); setAberto(false); campo.current?.focus();\n        }}>{v}</button>)}\n        {!opcoes.length && <p>{valores.length ? "Nenhum valor encontrado." : "Nenhum valor salvo. Digite um valor para começar."}</p>}\n      </div>\n    </div>}\n  </div>;\n}\n', 'frontend/src/pages/documentacao/PrepararPdfAdmin.tsx': 'import { useEffect, useRef, useState, type PointerEvent } from "react";\nimport { useAuth } from "../../auth/AuthContext";\nimport { api } from "../../services/api";\nimport CampoPdfComHistorico from "./CampoPdfComHistorico";\nimport "./PreparacaoPdf.css";\n\ntype EscopoServico = "conforme_solicitacao" | "desbaste" | "acabamento" | "peca_completa";\nexport type CamposCarimbo = { descricao: string; codigo_tecnico: string; material: string; quantidade: number; dureza: string; tratamento_termico: string; revestimento: string; escala: string; unidade: string; revisao: string; tolerancias_gerais: string; escopo_servico?: EscopoServico; sobremetal?: string; observacoes_servico?: string };\nexport type AreaCarimbo = { pagina: number; x: number; y: number; largura: number; altura: number; campos: CamposCarimbo };\nexport type PreparacaoPdf = { id: number; arquivo_id: number; versao: number; criado_em: string; administrador_nome: string; registro_interno: string; paginas: AreaCarimbo[] };\ntype ArquivoPdf = { id: number; nome_original: string; sha256: string; versao: number; preparacao_pdf_publicada_id?: number | null };\ntype PaginaPdf = { pagina: number; largura: number; altura: number };\ntype Info = { arquivo_id: number; sha256: string; paginas: PaginaPdf[]; preparacoes: PreparacaoPdf[] };\ntype CampoHistorico = Exclude<keyof CamposCarimbo, "escopo_servico">;\ntype ValorHistorico = { campo: CampoHistorico; valor: string };\ntype Historico = Partial<Record<CampoHistorico, string[]>>;\nconst BASE = "/administracao/preparacao-pdf";\nconst ESCOPOS: Record<EscopoServico, string> = { conforme_solicitacao: "Conforme solicitação", desbaste: "Somente desbaste", acabamento: "Somente acabamento", peca_completa: "Peça completa" };\nconst CAMPOS: [Exclude<keyof CamposCarimbo, "escopo_servico" | "sobremetal" | "observacoes_servico">, string, number][] = [\n  ["descricao", "Descrição da peça *", 80], ["codigo_tecnico", "Código técnico neutro", 30],\n  ["material", "Material *", 50], ["quantidade", "Quantidade *", 1000000],\n  ["dureza", "Dureza", 40], ["tratamento_termico", "Tratamento térmico", 60],\n  ["revestimento", "Revestimento", 60], ["escala", "Escala *", 24],\n  ["unidade", "Unidade *", 16], ["revisao", "Revisão", 16],\n  ["tolerancias_gerais", "Tolerâncias gerais (quando aplicáveis)", 180],\n];\nexport function erroPdf(erro: unknown) {\n  const falha = erro as { response?: { status?: number; data?: { detail?: unknown } } };\n  const detalhe = falha.response?.data?.detail;\n  const mensagens: Record<string, string> = {\n    pdf_invalido: "O conteúdo deste arquivo não é um PDF válido.",\n    pdf_protegido_nao_editavel: "Este PDF está protegido. Solicite uma cópia sem proteção para preparar o carimbo.",\n    pdf_formulario_ou_assinatura_nao_editavel: "Este PDF contém formulário ou assinatura. Solicite uma cópia simples do desenho.",\n    pdf_anotado_nao_editavel: "Este PDF contém anotações. Solicite uma cópia simples do desenho.",\n    pdf_rotacao_ou_recorte_nao_suportado: "Este PDF usa rotação ou recorte de página. Solicite uma cópia com as páginas orientadas normalmente.",\n    pdf_numero_paginas_nao_suportado: "A preparação aceita de 1 a 50 páginas.",\n    pdf_tamanho_pagina_nao_suportado: "O tamanho das páginas deste PDF não é suportado.",\n    pdf_excede_limite_preparacao: "A preparação aceita PDFs de até 30 MB.",\n    area_carimbo_muito_pequena: "A legenda precisa ter pelo menos 320 × 96 pontos para acomodar os campos. Mantenha a seleção dentro da legenda, preservando vistas, cotas e notas.",\n    area_corta_texto_imagem_ou_formulario: "A área corta um texto, imagem ou bloco do PDF. Ajuste a seleção para incluir o carimbo inteiro, sem atingir o desenho. PDFs digitalizados podem exigir preparação externa.",\n    area_corta_bloco_texto: "O PDF reúne textos de dentro e de fora da legenda em um mesmo bloco. Ajuste a seleção sem atingir cotas ou solicite um PDF com a legenda separada.",\n    pdf_estrutura_nao_suportada: "A estrutura deste PDF não permite trocar a legenda com segurança. Solicite outra exportação do desenho.",\n    pdf_divergencia_fora_legenda: "A comparação detectou uma alteração fora da legenda. A cópia foi recusada. Confira a seleção ou solicite outra exportação do desenho.",\n    texto_nao_cabe_no_carimbo: "Um dos campos não cabe na área escolhida. Confira os dados e as observações do serviço sem omitir informações necessárias. Ajuste a área somente dentro da legenda, preservando o desenho.",\n    pdf_nao_pode_ser_preparado: "Este PDF não pôde ser preparado. Confira o formato ou solicite outra cópia.",\n    pdf_nao_pode_ser_renderizado: "Não foi possível exibir esta página do PDF.",\n    documentacao_alterada_atualize: "O arquivo ou a liberação mudou. Feche a preparação, atualize a lista e revise novamente.",\n    arquivo_tecnico_sem_conteudo_valido: "O original está indisponível, foi alterado ou desvinculado. Atualize a lista.",\n    pdf_preparado_indisponivel: "Esta cópia está indisponível ou foi alterada. Gere e revise uma nova versão.",\n    preparacao_pdf_diverge_do_original: "A versão escolhida não corresponde ao original atual. Atualize e revise novamente.",\n    chave_operacao_reutilizada: "A operação mudou. Atualize antes de tentar novamente.",\n  };\n  if (typeof detalhe === "string" && mensagens[detalhe]) return mensagens[detalhe];\n  if (falha.response?.status === 401) return "Sua sessão expirou. Entre novamente.";\n  if (falha.response?.status === 403) return "Esta preparação exige acesso administrativo.";\n  if (falha.response?.status === 422) return "Confira os campos obrigatórios, o número da página e os limites da seleção. Use símbolos comuns como ±, ° e Ø.";\n  return "Não foi possível concluir a preparação. Confira a conexão e tente novamente.";\n}\n\nexport default function PrepararPdfAdmin({ arquivo, onFechar, onLiberar }: { arquivo: ArquivoPdf; onFechar: () => void; onLiberar: (p: PreparacaoPdf) => void }) {\n  const { user } = useAuth();\n  const contexto = user?.role === "admin" ? String(user.usuario_id) : "";\n  const vigente = useRef(contexto); vigente.current = contexto;\n  const [info, setInfo] = useState<Info | null>(null); const [erro, setErro] = useState("");\n  const [pagina, setPagina] = useState(1); const [areas, setAreas] = useState<AreaCarimbo[]>([]);\n  const [registro, setRegistro] = useState(""); const [ocupado, setOcupado] = useState(false);\n  const [escolhida, setEscolhida] = useState<PreparacaoPdf | null>(null); const [revisado, setRevisado] = useState(false);\n  const [imagem, setImagem] = useState(""); const [carregandoImagem, setCarregandoImagem] = useState(false);\n  const [carregando, setCarregando] = useState(true); const [mostrarCopia, setMostrarCopia] = useState(false);\n  const [baixando, setBaixando] = useState(false);\n  const [zoom, setZoom] = useState(1);\n  const [historico, setHistorico] = useState<Historico>({});\n  const [erroHistorico, setErroHistorico] = useState(""); const [estadoHistorico, setEstadoHistorico] = useState("");\n  const [tentativaHistorico, setTentativaHistorico] = useState(0);\n  const editados = useRef(new Map<string, ValorHistorico>());\n  const aceitos = useRef(new Set<string>()); const pendentes = useRef(new Set<string>());\n  const filaHistorico = useRef<Promise<boolean>>(Promise.resolve(true));\n  const ativa = useRef(true); const trava = useRef(false); const pedidos = useRef(new Set<AbortController>());\n  const chave = useRef({ pedido: "", valor: "" }); const inicio = useRef<{ x: number; y: number } | null>(null);\n  const area = areas.find(a => a.pagina === pagina); const tamanho = info?.paginas.find(p => p.pagina === pagina);\n  useEffect(() => { ativa.current = true; return () => { ativa.current = false; for (const c of pedidos.current) c.abort(); }; }, []);\n  useEffect(() => {\n    const c = new AbortController(); pedidos.current.add(c); let atual = true;\n    setInfo(null); setAreas([]); setEscolhida(null); setRevisado(false); setImagem(""); setErro(""); setCarregando(true);\n    editados.current = new Map(); aceitos.current = new Set(); pendentes.current = new Set(); filaHistorico.current = Promise.resolve(true); setEstadoHistorico("");\n    if (!contexto) { setCarregando(false); return; }\n    void api.get<Info>(`${BASE}/arquivos/${arquivo.id}`, { signal: c.signal, timeout: 30_000 }).then(({ data }) => {\n      if (atual && vigente.current === contexto) { setInfo(data); if (data.sha256 !== arquivo.sha256) setErro("O original mudou. Atualize a lista antes de preparar."); }\n    }).catch(e => { if (atual && !c.signal.aborted) setErro(erroPdf(e)); }).finally(() => { if (atual) setCarregando(false); pedidos.current.delete(c); });\n    return () => { atual = false; c.abort(); for (const outro of pedidos.current) outro.abort(); };\n  }, [arquivo.id, arquivo.sha256, contexto]);\n  useEffect(() => {\n    const c = new AbortController(); pedidos.current.add(c); let atual = true;\n    setHistorico({}); setErroHistorico("");\n    if (!contexto) return () => { pedidos.current.delete(c); };\n    void api.get<{ campos: Historico }>(`${BASE}/historico-campos`, { signal: c.signal, timeout: 15_000 }).then(({ data }) => {\n      if (atual && vigente.current === contexto) setHistorico(h => {\n        const resultado = { ...data.campos };\n        for (const k of Object.keys(h) as CampoHistorico[]) resultado[k] = [...new Set([...(h[k] ?? []), ...(resultado[k] ?? [])])];\n        return resultado;\n      });\n    }).catch(() => { if (atual && !c.signal.aborted && vigente.current === contexto) setErroHistorico("Não foi possível carregar o histórico. Tente carregar novamente."); })\n      .finally(() => pedidos.current.delete(c));\n    return () => { atual = false; c.abort(); };\n  }, [arquivo.id, contexto, tentativaHistorico]);\n  useEffect(() => {\n    const c = new AbortController(); pedidos.current.add(c); let atual = true; let url = "";\n    setImagem("");\n    if (!info || !contexto) return () => { pedidos.current.delete(c); };\n    setCarregandoImagem(true);\n    const rota = mostrarCopia && escolhida ? `${BASE}/versoes/${escolhida.id}/paginas/${pagina}` : `${BASE}/arquivos/${arquivo.id}/paginas/${pagina}`;\n    void api.get<Blob>(rota, { responseType: "blob", params: mostrarCopia && escolhida ? {} : { sha256: info.sha256 }, signal: c.signal, timeout: 45_000 }).then(({ data }) => {\n      if (atual && vigente.current === contexto) { url = URL.createObjectURL(data); setImagem(url); }\n    }).catch(e => { if (atual && !c.signal.aborted) setErro(erroPdf(e)); }).finally(() => { if (atual) setCarregandoImagem(false); pedidos.current.delete(c); });\n    return () => { atual = false; c.abort(); if (url) URL.revokeObjectURL(url); };\n  }, [arquivo.id, info, pagina, mostrarCopia, escolhida, contexto]);\n  function incluir() {\n    if (!tamanho || area) return;\n    const largura = Math.min(.95, Math.max(.21, 330 / tamanho.largura)); const altura = Math.min(.9, Math.max(.09, 140 / tamanho.altura));\n    setAreas(a => [...a, { pagina, x: 1 - largura - .01, y: 1 - altura - .01, largura, altura,\n      campos: { descricao: "", codigo_tecnico: `ARQUIVO-${arquivo.id}`, material: "", quantidade: 1, dureza: "", tratamento_termico: "", revestimento: "", escala: "", unidade: "mm", revisao: "", tolerancias_gerais: "", escopo_servico: "conforme_solicitacao", sobremetal: "", observacoes_servico: "" } }]);\n    setMostrarCopia(false);\n  }\n  function mudar(alteracao: Partial<AreaCarimbo>) {\n    if (alteracao.campos && area) for (const k of Object.keys(alteracao.campos) as (keyof CamposCarimbo)[]) {\n      if (k !== "escopo_servico" && alteracao.campos[k] !== area.campos[k]) editados.current.set(`${pagina}:${k}`, { campo: k, valor: String(alteracao.campos[k] ?? "") });\n    }\n    setErro(""); setAreas(a => a.map(v => v.pagina === pagina ? { ...v, ...alteracao } : v));\n  }\n  function guardarValores(valores: ValorHistorico[]) {\n    if (!contexto) return Promise.resolve(false);\n    const ctx = contexto; const itens: ValorHistorico[] = []; const pendentesDesteContexto = pendentes.current; const aceitosDesteContexto = aceitos.current;\n    for (const item of valores) {\n      const valor = item.valor.trim(); const chave = `${item.campo}\\n${valor}`;\n      if (!valor || aceitosDesteContexto.has(chave) || pendentesDesteContexto.has(chave)) continue;\n      pendentesDesteContexto.add(chave); itens.push({ ...item, valor });\n    }\n    if (!itens.length) return filaHistorico.current;\n    const salvar = async () => {\n      const chaves = itens.map(v => `${v.campo}\\n${v.valor}`);\n      if (!ativa.current || vigente.current !== ctx) { chaves.forEach(v => pendentesDesteContexto.delete(v)); return false; }\n      const c = new AbortController(); pedidos.current.add(c); setEstadoHistorico("Guardando valores no histórico…");\n      try {\n        await api.post(`${BASE}/historico-campos`, { itens }, { signal: c.signal, timeout: 15_000 });\n        if (!ativa.current || vigente.current !== ctx || c.signal.aborted) return false;\n        chaves.forEach(v => aceitosDesteContexto.add(v));\n        setHistorico(h => {\n          const atualizado = { ...h };\n          for (const { campo, valor } of itens) atualizado[campo] = [valor, ...(atualizado[campo] ?? []).filter(v => v.replace(/\\s+/g, " ").toLowerCase() !== valor.replace(/\\s+/g, " ").toLowerCase())];\n          return atualizado;\n        });\n        setErroHistorico(""); setEstadoHistorico("Valores guardados no histórico."); return true;\n      } catch {\n        if (ativa.current && vigente.current === ctx && !c.signal.aborted) { setErroHistorico("Não foi possível guardar os valores no histórico. Confira os campos e tente guardar novamente."); setEstadoHistorico(""); }\n        return false;\n      } finally { chaves.forEach(v => pendentesDesteContexto.delete(v)); pedidos.current.delete(c); }\n    };\n    filaHistorico.current = filaHistorico.current.then(salvar, salvar);\n    return filaHistorico.current;\n  }\n  function guardarCampo(campo: CampoHistorico, valor: string) {\n    editados.current.set(`${pagina}:${campo}`, { campo, valor });\n    return guardarValores([{ campo, valor }]);\n  }\n  function campoHistorico(k: CampoHistorico, label: string, limite: number, multiline = false, placeholder?: string) {\n    if (!area) return null;\n    return <CampoPdfComHistorico key={k} label={label} nome={label.replace(/\\s*\\*.*/, "").replace(/\\s*\\(.*/, "")}\n      valor={area.campos[k] ?? ""} valores={historico[k] ?? []} limite={limite} multiline={multiline} numero={k === "quantidade"}\n      placeholder={placeholder} disabled={ocupado} onMudar={valor => mudar({ campos: { ...area.campos, [k]: k === "quantidade" ? Number(valor) : valor } })}\n      onGuardar={valor => { void guardarCampo(k, valor); }} />;\n  }\n  async function fechar() { await guardarValores([...editados.current.values()]); if (ativa.current && vigente.current === contexto) onFechar(); }\n  function ponto(e: PointerEvent<SVGSVGElement>) {\n    const b = e.currentTarget.getBoundingClientRect();\n    return { x: Math.max(0, Math.min(1, (e.clientX - b.left) / b.width)), y: Math.max(0, Math.min(1, (e.clientY - b.top) / b.height)) };\n  }\n  function arrastar(e: PointerEvent<SVGSVGElement>) {\n    if (!inicio.current) return;\n    const p = ponto(e); mudar({ x: Math.min(p.x, inicio.current.x), y: Math.min(p.y, inicio.current.y), largura: Math.max(.00001, Math.abs(p.x - inicio.current.x)), altura: Math.max(.00001, Math.abs(p.y - inicio.current.y)) });\n  }\n  const areaInsuficiente = areas.some(a => {\n    const p = info?.paginas.find(p => p.pagina === a.pagina);\n    return !p || a.largura * p.largura < 320 - 0.000001 || a.altura * p.altura < 96 - 0.000001;\n  });\n  const valido = !areaInsuficiente && areas.length > 0 && areas.every(a => a.campos.descricao.trim() && a.campos.material.trim() && a.campos.quantidade > 0 && a.campos.escala.trim() && a.campos.unidade.trim() && a.x + a.largura <= 1.00000001 && a.y + a.altura <= 1.00000001);\n  async function gerar() {\n    if (!info || !contexto || trava.current || !valido || registro.trim().length < 3 || info.sha256 !== arquivo.sha256) return;\n    trava.current = true; setOcupado(true); setErro(""); const ctx = contexto;\n    const c = new AbortController(); pedidos.current.add(c);\n    const corpo = { sha256: info.sha256, versao_liberacao: arquivo.versao, paginas: areas, registro_interno: registro.trim() };\n    const serializado = JSON.stringify(corpo);\n    if (chave.current.pedido !== serializado) chave.current = { pedido: serializado, valor: crypto.randomUUID() };\n    try {\n      await guardarValores([...editados.current.values()]);\n      if (!ativa.current || vigente.current !== ctx || c.signal.aborted) return;\n      const { data } = await api.post<PreparacaoPdf>(`${BASE}/arquivos/${arquivo.id}`, { ...corpo, chave_operacao: chave.current.valor }, { signal: c.signal, timeout: 90_000 });\n      if (ativa.current && vigente.current === ctx && !c.signal.aborted) {\n        setInfo(i => i && { ...i, preparacoes: [data, ...i.preparacoes.filter(p => p.id !== data.id)] });\n        setEscolhida(data); setMostrarCopia(true); setRevisado(false); setPagina(data.paginas[0].pagina);\n      }\n    } catch (e) { if (ativa.current && vigente.current === ctx && !c.signal.aborted) setErro(erroPdf(e)); }\n    finally { trava.current = false; pedidos.current.delete(c); if (ativa.current && vigente.current === ctx) setOcupado(false); }\n  }\n  async function baixar() {\n    if (!escolhida || baixando || !contexto) return; const p = escolhida; const ctx = contexto;\n    const c = new AbortController(); pedidos.current.add(c); setBaixando(true); setErro("");\n    try {\n      const { data } = await api.get<Blob>(`${BASE}/versoes/${p.id}/download`, { responseType: "blob", signal: c.signal, timeout: 45_000 });\n      if (!ativa.current || vigente.current !== ctx || c.signal.aborted) return;\n      const url = URL.createObjectURL(data); const a = document.createElement("a"); a.href = url; a.download = `mec-arquivo-${arquivo.id}-versao-${p.versao}.pdf`; document.body.appendChild(a); a.click(); a.remove(); window.setTimeout(() => URL.revokeObjectURL(url), 30_000);\n    } catch (e) { if (ativa.current && vigente.current === ctx && !c.signal.aborted) setErro(erroPdf(e)); }\n    finally { pedidos.current.delete(c); if (ativa.current && vigente.current === ctx) setBaixando(false); }\n  }\n  if (!contexto) return <p role="alert">A preparação de PDF exige acesso administrativo.</p>;\n  return <section className="pdf48-panel" aria-label="Preparação do PDF para cotação">\n    <div className="pdf48-topo"><div><h2>Preparar PDF com carimbo MEC-Serviços</h2><p>{arquivo.nome_original}</p></div><button disabled={ocupado} onClick={() => void fechar()}>Fechar preparação</button></div>\n    <p className="doc42-alert">Selecione somente o carimbo e informe os dados necessários ao serviço contratado. Para desbaste, registre o sobremetal quando definido. Confira também as outras áreas e páginas: a preparação não identifica automaticamente todos os dados do cliente.</p>\n    <p>Gerar uma cópia não altera a liberação atual. O fornecedor receberá a nova versão somente após a revisão e a liberação.</p>\n    <p>Clique na setinha de cada campo para selecionar um valor do histórico. Você também pode digitar um valor novo: ele será guardado ao sair do campo.</p>\n    {estadoHistorico && <p role="status">{estadoHistorico}</p>}\n    {erroHistorico && <div className="doc42-alert" role="alert"><p>{erroHistorico}</p><button disabled={ocupado} onClick={() => { setTentativaHistorico(v => v + 1); void guardarValores([...editados.current.values()]); }}>Tentar histórico novamente</button></div>}\n    {erro && <p role="alert" className="doc42-alert doc42-erro">{erro}</p>}\n    {carregando && <p role="status">Conferindo PDF…</p>}\n    {info && <>\n      <div className="pdf48-barra"><label>Página<select value={pagina} disabled={ocupado} onChange={e => { setPagina(Number(e.target.value)); setRevisado(false); }}>{info.paginas.map(p => <option key={p.pagina} value={p.pagina}>{p.pagina} de {info.paginas.length}{areas.some(a => a.pagina === p.pagina) ? " · carimbo configurado" : ""}</option>)}</select></label>\n        <label>Ampliação<select value={zoom} onChange={e => setZoom(Number(e.target.value))}><option value={1}>100%</option><option value={2}>200%</option><option value={3}>300%</option></select></label>\n        <button disabled={ocupado || !escolhida} onClick={() => setMostrarCopia(v => !v)}>{mostrarCopia ? "Ver original" : "Ver cópia preparada"}</button>\n        {!mostrarCopia && <button disabled={ocupado} onClick={() => area ? setAreas(a => a.filter(v => v.pagina !== pagina)) : incluir()}>{area ? "Remover carimbo desta página" : "Incluir carimbo nesta página"}</button>}\n      </div>\n      {carregandoImagem && <p role="status">Carregando página…</p>}\n      {imagem && tamanho && <div className="pdf48-rolagem"><div className="pdf48-pagina" style={{ width: `${zoom * 100}%`, aspectRatio: `${tamanho.largura} / ${tamanho.altura}` }}><img src={imagem} alt={`Página ${pagina} ${mostrarCopia ? "da cópia preparada" : "do original"}`} />\n        {!mostrarCopia && area && <svg viewBox="0 0 1000 1000" preserveAspectRatio="none" aria-label="Área do carimbo; arraste para selecionar" onPointerDown={e => { if (ocupado) return; e.currentTarget.setPointerCapture(e.pointerId); inicio.current = ponto(e); }} onPointerMove={arrastar} onPointerUp={e => { arrastar(e); inicio.current = null; e.currentTarget.releasePointerCapture(e.pointerId); }} onPointerCancel={() => { inicio.current = null; }}><rect x={area.x * 1000} y={area.y * 1000} width={area.largura * 1000} height={area.altura * 1000} /></svg>}\n      </div></div>}\n      {!mostrarCopia && area && <fieldset disabled={ocupado} className="pdf48-config"><legend>Carimbo da página {pagina}</legend><p>Arraste sobre a página ou ajuste os percentuais. Inclua a logo e a identificação antigas por inteiro; preserve cotas, vistas e notas fora do carimbo.</p>\n        <div className="pdf48-coordenadas">{([["x", "Esquerda (%)"], ["y", "Topo (%)"], ["largura", "Largura (%)"], ["altura", "Altura (%)"]] as const).map(([k, label]) => <label key={k}>{label}<input type="number" min={0} max={100} step="0.001" value={Number((area[k] * 100).toFixed(3))} onChange={e => mudar({ [k]: Number(e.target.value) / 100 })} /></label>)}</div>\n        {tamanho && <p>Área: {(area.largura * tamanho.largura).toFixed(1)} × {(area.altura * tamanho.altura).toFixed(1)} pontos. Mínimo: 320 × 96. O formato compacto é usado automaticamente em legendas com altura inferior a 132 pontos.</p>}\n        {tamanho && (area.largura * tamanho.largura < 320 - 0.000001 || area.altura * tamanho.altura < 96 - 0.000001) && <p className="doc42-alert doc42-erro" role="alert">A área selecionada é pequena para o carimbo. Ajuste somente dentro da legenda; preserve as vistas, cotas e notas.</p>}\n        <div className="pdf48-campos"><label>Escopo da usinagem<select value={area.campos.escopo_servico ?? "conforme_solicitacao"} onChange={e => mudar({ campos: { ...area.campos, escopo_servico: e.target.value as EscopoServico } })}>{Object.entries(ESCOPOS).map(([k, label]) => <option key={k} value={k}>{label}</option>)}</select></label>\n          {campoHistorico("sobremetal", "Sobremetal (quando definido)", 80, false, "Informe valor, unidade e superfícies.")}\n          {campoHistorico("observacoes_servico", "Observações do serviço", 180, true, "Etapas e condições acordadas para esta peça.")}</div>\n        <p>Preencha dureza, tratamentos, revestimento e tolerâncias apenas quando fizerem parte do serviço. O escopo não altera as cotas e notas que já estão nas vistas do desenho.</p>\n        <div className="pdf48-campos">{CAMPOS.map(([k, label, limite]) => campoHistorico(k, label, limite, k === "tolerancias_gerais"))}</div>\n      </fieldset>}\n      {!mostrarCopia && <div className="pdf48-gerar"><p>{areas.length} página(s) configurada(s). As outras páginas permanecem no documento.</p><label>Registro interno da preparação<textarea maxLength={2000} value={registro} disabled={ocupado} onChange={e => setRegistro(e.target.value)} placeholder="Especificações conferidas e área substituída." /></label><button disabled={ocupado || !valido || registro.trim().length < 3 || info.sha256 !== arquivo.sha256} onClick={() => void gerar()}>{ocupado ? "Preparando cópia…" : "Gerar cópia para revisão"}</button></div>}\n      {!!info.preparacoes.length && <div className="pdf48-versoes"><h3>Cópias preparadas</h3><label>Versão para revisar<select value={escolhida?.id ?? ""} disabled={ocupado} onChange={e => { const p = info.preparacoes.find(v => v.id === Number(e.target.value)) ?? null; setEscolhida(p); setMostrarCopia(!!p); setRevisado(false); if (p) setPagina(p.paginas[0].pagina); }}><option value="">Selecione uma cópia</option>{info.preparacoes.map(p => <option key={p.id} value={p.id}>Versão {p.versao}{p.id === arquivo.preparacao_pdf_publicada_id ? " · liberada" : ""} · {p.administrador_nome}</option>)}</select></label>\n        {escolhida && <><p>Versão {escolhida.versao} · {escolhida.criado_em}<br />{escolhida.registro_interno}</p>{escolhida.paginas.map(p => <p key={p.pagina}>Página {p.pagina}: {p.campos.escopo_servico && p.campos.escopo_servico !== "conforme_solicitacao" ? ESCOPOS[p.campos.escopo_servico] : p.campos.sobremetal || p.campos.observacoes_servico ? ESCOPOS.conforme_solicitacao : "Escopo não indicado nesta cópia"}{p.campos.sobremetal && <> · Sobremetal: {p.campos.sobremetal}</>}{p.campos.observacoes_servico && <> · {p.campos.observacoes_servico}</>}</p>)}<div className="doc42-acoes"><button disabled={baixando} onClick={() => void baixar()}>{baixando ? "Baixando…" : "Baixar cópia para revisar"}</button></div><label className="doc42-check"><input type="checkbox" checked={revisado} disabled={ocupado} onChange={e => setRevisado(e.target.checked)} />Conferi todas as páginas da cópia, o escopo do serviço, as especificações aplicáveis e a ausência de contatos ou identificação do cliente.</label><button disabled={ocupado || !revisado || escolhida.id === arquivo.preparacao_pdf_publicada_id} onClick={() => onLiberar(escolhida)}>Liberar esta versão para cotação</button></>}\n      </div>}\n    </>}\n  </section>;\n}\n', 'frontend/src/pages/documentacao/PreparacaoPdf.css': '.pdf48-panel{border:1px solid #7198c5;background:#101b29;border-radius:12px;margin-top:20px;padding:20px;color:#e4edf7}.pdf48-topo{display:flex;align-items:start;justify-content:space-between;gap:16px}.pdf48-topo h2{margin:0 0 8px}.pdf48-panel p{color:#b8c8dc}.pdf48-barra{display:flex;flex-wrap:wrap;gap:12px;align-items:end;margin:16px 0}.pdf48-panel select{background:#0a1420;border:1px solid #587393;color:#e5effb;border-radius:7px;padding:10px;font:inherit}.pdf48-pagina{position:relative;width:100%;background:#fff;overflow:hidden;border:1px solid #7890ad}.pdf48-pagina img{width:100%;height:100%;display:block;object-fit:fill}.pdf48-pagina svg{position:absolute;inset:0;width:100%;height:100%;touch-action:none;cursor:crosshair}.pdf48-pagina rect{fill:#f2912940;stroke:#b25200;stroke-width:2;vector-effect:non-scaling-stroke}.pdf48-config{border:1px solid #587393;border-radius:8px;padding:18px;margin-top:18px;min-width:0}.pdf48-config legend{color:#e5effb;padding:0 8px}.pdf48-campos,.pdf48-coordenadas{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px}.pdf48-campos{grid-template-columns:repeat(3,minmax(0,1fr));margin-top:18px}.pdf48-campos label:last-child{grid-column:1/-1}.pdf48-panel input:not([type=checkbox]),.pdf48-panel textarea{min-width:0;width:100%;box-sizing:border-box}.pdf48-gerar{margin-top:20px}.pdf48-gerar button{margin-top:12px}.pdf48-versoes{margin-top:24px;border-top:1px solid #587393;padding-top:12px}.pdf48-versoes select{max-width:100%}.pdf48-panel button:focus-visible,.pdf48-panel input:focus-visible,.pdf48-panel select:focus-visible,.pdf48-panel textarea:focus-visible{outline:2px solid #82bdff;outline-offset:2px}@media(max-width:800px){.pdf48-campos,.pdf48-coordenadas{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:500px){.pdf48-panel{padding:12px}.pdf48-topo{flex-direction:column}.pdf48-campos,.pdf48-coordenadas{grid-template-columns:1fr}}\n.pdf48-rolagem{max-height:75vh;overflow:auto;background:#fff;border:1px solid #7890ad;margin:12px 0}.pdf48-rolagem .pdf48-pagina{border:0}\n.pdf50-campo{position:relative;min-width:0}.pdf48-campos>.pdf50-campo:last-child{grid-column:1/-1}.pdf50-controle{position:relative;display:block}.pdf48-panel .pdf50-controle input,.pdf48-panel .pdf50-controle textarea{padding-right:46px}.pdf48-panel .pdf50-seta{position:absolute;right:1px;top:1px;bottom:1px;width:40px;min-width:0;margin:0;padding:0;border:0;border-left:1px solid #587393;border-radius:0 6px 6px 0;background:#18304b;color:#e5effb;font-size:22px}.pdf48-panel .pdf50-seta:hover{background:#264b72}.pdf50-menu{position:absolute;left:0;right:0;top:100%;z-index:20;background:#0a1420;border:1px solid #7198c5;border-radius:8px;box-shadow:0 8px 22px #0008;padding:8px;margin-top:4px}.pdf50-menu [role=listbox]{max-height:230px;overflow:auto;margin-top:6px}.pdf48-panel .pdf50-menu [role=option]{display:block;width:100%;margin:0;padding:10px;text-align:left;white-space:pre-wrap;overflow-wrap:anywhere;border:0;border-radius:4px;background:transparent;color:#e5effb}.pdf48-panel .pdf50-menu [role=option]:hover,.pdf48-panel .pdf50-menu [role=option]:focus-visible{background:#264b72}.pdf50-menu p{font-size:.9rem;margin:8px}.pdf50-controle input[type=number]{appearance:textfield}.pdf50-controle input[type=number]::-webkit-inner-spin-button,.pdf50-controle input[type=number]::-webkit-outer-spin-button{appearance:none;margin:0}\n', 'tests/test_historico_campos_pdf_d50.py': '"""Histórico persistente por ADM, campos válidos e consultas sem alterar PDFs."""\nfrom concurrent.futures import ThreadPoolExecutor\nfrom pathlib import Path\nfrom uuid import uuid4\nimport json\nimport pytest\nfrom sqlalchemy import select\nfrom backend.app.models.historico_campos_pdf import HistoricoCampoPdf\nfrom backend.app.models.preparacao_pdf import PreparacaoPdfCotacao\nfrom backend.app.core.armazenamento_acesso import UsuarioAcesso\nfrom backend.app.schemas.historico_campos_pdf import GuardarHistoricoPdf, LIMITES\nfrom backend.app.services.historico_campos_pdf import ServicoHistoricoCamposPdf\nfrom test_acesso_d30 import ambiente, modelo_acessos, entrar, BASE, SENHA\nfrom test_preparacao_pdf_d48 import pedido, desenho, contagens\nfrom test_documentacao_cotacao_d42 import upload\n\npytestmark = pytest.mark.acesso_real\nURL = BASE+"/administracao/preparacao-pdf/historico-campos"\n\ndef guardar(http, campo, valor):\n    r=http.post(URL,json={"itens":[{"campo":campo,"valor":valor}]})\n    assert r.status_code==200,r.text\n    return r.json()\n\n\ndef test_digitacao_sem_gerar_pdf_persiste_e_reaparece_apos_nova_sessao(ambiente):\n    http,_,sessoes,_=ambiente; entrar(http,"admin")\n    assert all(not v for v in http.get(URL).json()["campos"].values())\n    guardar(http,"material","FORMADUR 2083");guardar(http,"sobremetal","0,5 mm nas faces")\n    http.cookies.clear(); entrar(http,"admin")\n    campos=http.get(URL).json()["campos"]\n    assert campos["material"]==["FORMADUR 2083"] and campos["sobremetal"]==["0,5 mm nas faces"]\n    assert contagens(sessoes)==(0,0,0)\n\n\ndef test_valor_recente_sobe_na_lista_sem_duplicatas_por_caixa_ou_espacos(ambiente):\n    http,_,sessoes,_=ambiente; entrar(http,"admin")\n    guardar(http,"material","  Formadur  2083  ");guardar(http,"material","TYRAX ESR")\n    guardar(http,"material","FORMADUR 2083")\n    assert http.get(URL).json()["campos"]["material"]==["FORMADUR 2083","TYRAX ESR"]\n    with sessoes() as db: assert len(db.scalars(select(HistoricoCampoPdf)).all())==2\n\n\ndef test_campos_nao_se_misturam_e_texto_multilinha_e_preservado(ambiente):\n    http,_,_,_=ambiente; entrar(http,"admin")\n    guardar(http,"descricao","INSERTO");guardar(http,"material","INSERTO")\n    texto="Face A: desbaste.\\nFace B: sem usinagem."\n    guardar(http,"observacoes_servico",texto)\n    campos=http.get(URL).json()["campos"]\n    assert campos["descricao"]==campos["material"]==["INSERTO"]\n    assert campos["observacoes_servico"]==[texto] and campos["tratamento_termico"]==[]\n\n\ndef test_historico_exclusivo_do_adm_da_sessao_sem_id_forjado(ambiente):\n    http,acesso,_,_=ambiente; entrar(http,"admin");guardar(http,"material","MATERIAL ADMIN 1")\n    acesso.criar_usuario("Outro ADM","outro@teste.local","admin",None,SENHA,deve_alterar_senha=False)\n    r=http.post(BASE+"/autenticacao/entrar",json={"email":"outro@teste.local","senha":SENHA})\n    assert r.status_code==200;http.headers["X-MEC-CSRF"]=r.json()["csrf"]\n    assert http.get(URL,params={"usuario_admin_id":1}).json()["campos"]["material"]==[]\n    guardar(http,"material","MATERIAL ADMIN 2")\n    entrar(http,"admin");assert http.get(URL).json()["campos"]["material"]==["MATERIAL ADMIN 1"]\n    assert http.post(URL,json={"usuario_admin_id":2,"itens":[{"campo":"material","valor":"FORJADO"}]}).status_code==422\n\n\n@pytest.mark.parametrize("perfil",[None,"cliente","fornecedor"])\ndef test_outros_perfis_nao_leem_nem_gravam_historico(ambiente,perfil):\n    http,_,sessoes,_=ambiente\n    if perfil: entrar(http,perfil)\n    else: http.cookies.clear()\n    esperado=403 if perfil else 401\n    assert http.get(URL,headers={"X-Perfil":"admin"}).status_code==esperado\n    assert http.post(URL,json={"itens":[{"campo":"material","valor":"TYRAX"}]},headers={"X-Perfil":"admin"}).status_code==esperado\n    with sessoes() as db: assert not db.scalars(select(HistoricoCampoPdf)).all()\n\n\ndef test_csrf_invalido_recusa_sem_gravar(ambiente):\n    http,_,sessoes,_=ambiente;entrar(http,"admin")\n    assert http.post(URL,json={"itens":[{"campo":"material","valor":"TYRAX"}]},headers={"X-MEC-CSRF":"errado"}).status_code==403\n    with sessoes() as db:assert not db.scalars(select(HistoricoCampoPdf)).all()\n\n\n@pytest.mark.parametrize("campo,valor",[("material",""),("material","x"*51),("material","中文"),\n    ("descricao","x\\x00"),("quantidade","0"),("quantidade","1.5"),("quantidade","1000001"),\n    ("registro_interno","Segredo"),("sha256","a"*64),("escopo_servico","desbaste")])\ndef test_valores_invalidos_e_campos_internos_nao_entram_no_historico(ambiente,campo,valor):\n    http,_,sessoes,_=ambiente;entrar(http,"admin")\n    r=http.post(URL,json={"itens":[{"campo":"material","valor":"Valor valido"},{"campo":campo,"valor":valor}]})\n    assert r.status_code==422,r.text\n    with sessoes() as db:assert not db.scalars(select(HistoricoCampoPdf)).all()\n\n\ndef test_lote_completo_e_quantidade_normalizada_sem_publicacao(ambiente):\n    http,_,sessoes,_=ambiente;entrar(http,"admin")\n    valores={campo:("0018" if campo=="quantidade" else "Valor "+campo[:3]) for campo in LIMITES}\n    r=http.post(URL,json={"itens":[{"campo":k,"valor":v} for k,v in valores.items()]})\n    assert r.status_code==200 and r.json()["guardados"]==13\n    campos=http.get(URL).json()["campos"]\n    assert campos["quantidade"]==["18"] and contagens(sessoes)==(0,0,0)\n\n\ndef test_duas_abas_salvam_um_unico_valor(ambiente):\n    _,_,sessoes,_=ambiente;dados=GuardarHistoricoPdf(itens=[{"campo":"material","valor":"TYRAX ESR"}])\n    admin=UsuarioAcesso(1,"Admin","admin@teste.local","admin",None,False)\n    def salvar(_):\n        with sessoes() as db:return ServicoHistoricoCamposPdf(db).guardar(dados,admin)\n    with ThreadPoolExecutor(max_workers=2) as pool:resultados=list(pool.map(salvar,range(2)))\n    assert resultados==[{"guardados":1},{"guardados":1}]\n    with sessoes() as db:assert len(db.scalars(select(HistoricoCampoPdf)).all())==1\n\n\ndef test_configuracoes_antigas_alimentam_sugestoes_sem_modificar_versoes(ambiente):\n    http,_,sessoes,_=ambiente;a=upload(http,conteudo=desenho());dados=pedido(a)\n    configuracao=json.dumps(dados["paginas"],ensure_ascii=False)\n    with sessoes() as db:\n        registros=[]\n        for versao,autor,cfg in [(1,1,configuracao),(2,99,configuracao),(3,1,\'corrompido\')]:\n            p=PreparacaoPdfCotacao(arquivo_id=a["id"],versao=versao,sha256_original=a["sha256"],sha256="b"*64,\n                tamanho_bytes=1,caminho_arquivo="inexistente.pdf",configuracao_json=cfg,\n                registro_interno="SEGREDO INTERNO",usuario_admin_id=autor,administrador_nome="ADM",criado_em=f"2026-10-09T10:00:0{versao}Z",\n                chave_operacao=str(uuid4()),pedido_sha256="c"*64)\n            db.add(p);registros.append(p)\n        db.commit();antes=[p.configuracao_json for p in registros]\n    entrar(http,"admin");r=http.get(URL);assert r.status_code==200,r.text\n    campos=r.json()["campos"]\n    assert campos["material"]==["TYRAX ESR"] and campos["quantidade"]==["20"]\n    assert "SEGREDO" not in r.text and "registro_interno" not in campos and "sha256" not in campos\n    with sessoes() as db:\n        assert [p.configuracao_json for p in db.scalars(select(PreparacaoPdfCotacao).order_by(PreparacaoPdfCotacao.id))]==antes\n        assert not db.scalars(select(HistoricoCampoPdf)).all()\n\n\ndef test_historico_nao_descarta_valores_antigos(ambiente):\n    http,_,_,_=ambiente;entrar(http,"admin")\n    r=http.post(URL,json={"itens":[{"campo":"material","valor":f"Material {n}"} for n in range(120)]})\n    assert r.status_code==200,r.text\n    assert len(http.get(URL).json()["campos"]["material"])==120\n', 'D50_CONTRATO_HISTORICO_CAMPOS_PDF.txt': 'MEC-Serviços D50 — Setinhas e histórico dos campos do PDF\n\nCOMO FUNCIONA\nCada campo da legenda tem uma setinha à direita. Clique para abrir os valores\njá utilizados naquele campo. A busca da lista ajuda a localizar uma opção.\nDepois de selecionar, o campo continua editável. Também é possível digitar\num valor novo, que será guardado ao sair do campo.\n\nO histórico inclui descrição, código técnico neutro, material, quantidade,\ndureza, tratamento térmico, revestimento, escala, unidade, revisão,\ntolerâncias gerais, sobremetal e observações do serviço.\nO escopo da usinagem continua com suas opções da D49.\nSomente o campo escolhido recebe o valor selecionado; não há preenchimento\nautomático de outras informações da peça.\n\nPERSISTÊNCIA\nCada ADM tem seu próprio histórico, disponível em outra sessão ou navegador.\nValores dos PDFs que esse mesmo ADM já preparou aparecem nas sugestões,\nincluindo versões anteriores à D50. Essa leitura não altera os documentos.\nUm valor reutilizado não cria duplicatas por diferença de maiúsculas ou espaços.\nOs valores válidos continuam disponíveis; não são descartados por antiguidade.\nCampos vazios, dados inválidos, coordenadas e registro interno não são guardados\ncomo sugestões. Cliente e fornecedor não acessam o histórico administrativo.\n\nINSTALAÇÃO\nExige D49 concluída, com relatório RESULTADO=OK.\n1. Salve MEC_SERVICOS_V0_1_D50_HISTORICO_CAMPOS_PDF.py na raiz do projeto.\n2. Pare backend e frontend com Ctrl+C em seus terminais.\n3. Execute cada comando em sua própria linha no PowerShell:\n   cd C:\\Users\\Omega\\Desktop\\MEC-Servicos\n   .\\.venv\\Scripts\\python.exe .\\MEC_SERVICOS_V0_1_D50_HISTORICO_CAMPOS_PDF.py\n4. Aguarde RESULTADO=OK. A saída mostra os testes e o build ao vivo.\nO instalador cria backup dos arquivos alterados, do build e dos dois bancos.\nA nova tabela do histórico é criada em transação somente após os testes,\no build e a conferência de preservação dos registros existentes.\n\nATIVAÇÃO\nBackend, na raiz:\n   .\\.venv\\Scripts\\python.exe .\\MEC_SERVICOS_INICIAR_TESTE_LOCAL.py\nFrontend, em outro PowerShell:\n   cd C:\\Users\\Omega\\Desktop\\MEC-Servicos\\frontend\n   npm.cmd run dev -- --host localhost --port 5173 --strictPort\nAbra http://localhost:5173 e atualize com Ctrl+F5.\n\nTESTE MANUAL\n1. Entre como ADM em Administração > Arquivos Técnicos.\n2. Abra Preparar PDF com nossa logo e inclua a legenda da página.\n3. Clique na setinha do Material: os materiais já usados nos seus PDFs\n   devem aparecer. Busque e selecione um deles; confira o valor no campo.\n4. Digite outro valor válido e clique no próximo campo. Aguarde a indicação\n   “Valores guardados no histórico”. Não é preciso gerar PDF para guardar.\n5. Feche e abra a preparação de outro PDF. Clique na setinha do Material:\n   o valor digitado deve estar disponível, sem alterar os demais campos.\n6. Repita com dureza, tratamento, escala ou observações, quando aplicáveis.\n7. Confirme que o histórico permanece após sair e entrar novamente como ADM.\n8. A geração, revisão e liberação da cópia continuam seguindo o fluxo da D49.\n   Selecionar um valor do histórico não gera PDF nem libera documentação.\n\nSe aparecer falha ao carregar ou guardar o histórico, os campos continuam\neditáveis. Use Tentar histórico novamente para repetir a operação.\nOriginais, PDFs preparados, liberações, contas, senhas e históricos de negócio\nsão preservados pela atualização. Os testes usam bancos isolados.\n'}

