DDL_D50 = {'historico_campos_pdf': 'CREATE TABLE historico_campos_pdf (\n\tid INTEGER NOT NULL, \n\tusuario_admin_id INTEGER NOT NULL, \n\tcampo VARCHAR(32) NOT NULL, \n\tchave_valor VARCHAR(64) NOT NULL, \n\tvalor VARCHAR(180) NOT NULL, \n\tatualizado_em VARCHAR(32) NOT NULL, \n\tPRIMARY KEY (id), \n\tCONSTRAINT uq_historico_campo_pdf_valor UNIQUE (usuario_admin_id, campo, chave_valor), \n\tCONSTRAINT ck_historico_campo_pdf_usuario CHECK (usuario_admin_id > 0)\n)'}

INDICES_D50 = {'ix_historico_campo_pdf_usuario_data': 'CREATE INDEX ix_historico_campo_pdf_usuario_data ON historico_campos_pdf (usuario_admin_id, atualizado_em)'}


def conferir_schema_d50(conexao):
    presentes = {n for (n,) in conexao.execute("SELECT name FROM sqlite_master WHERE type='table'")} & set(DDL_D50)
    if not presentes: return False
    def normal(sql): return "".join(sql.split()).lower()
    for nome, ddl in {**DDL_D50, **INDICES_D50}.items():
        row = conexao.execute("SELECT sql FROM sqlite_master WHERE name=?", (nome,)).fetchone()
        if not row or not row[0] or normal(row[0]) != normal(ddl):
            raise RuntimeError("Estrutura D50 divergente; banco preservado: " + nome)
    return True

def preparar_tabelas_d50(banco, acesso, negocio_antes, contas_antes):
    with closing(sqlite3.connect(banco.as_uri()+"?mode=rw", uri=True)) as negocio, closing(sqlite3.connect(acesso.as_uri()+"?mode=rw", uri=True)) as contas:
        negocio.execute("PRAGMA foreign_keys=ON")
        negocio.execute("BEGIN IMMEDIATE"); contas.execute("BEGIN IMMEDIATE")
        try:
            if historico(negocio) != negocio_antes or historico(contas) != contas_antes:
                raise RuntimeError("Banco mudou durante a validação; registros externos preservados.")
            existentes = conferir_schema_d50(negocio)
            if not existentes:
                for ddl in DDL_D50.values(): negocio.execute(ddl)
                for ddl in INDICES_D50.values(): negocio.execute(ddl)
            if not conferir_schema_d50(negocio): raise RuntimeError("Tabela do histórico D50 não confirmada.")
            if historico(negocio, negocio_antes) != negocio_antes or historico(contas) != contas_antes:
                raise RuntimeError("Histórico mudou durante a conferência; banco preservado.")
            if negocio.execute("PRAGMA integrity_check").fetchall() != [("ok",)] or negocio.execute("PRAGMA foreign_key_check").fetchall():
                raise RuntimeError("Integridade do banco não confirmada.")
            negocio.commit()
            return 0 if existentes else len(DDL_D50)
        except BaseException:
            negocio.rollback()
            raise
        finally: contas.rollback()


if __name__ == "__main__":
    raise SystemExit(main())
